  "75E1": "\u00F9", // u + grave = ù

  // Combining circumflex (0xE2)
  "41E2": "\u00C2", // A + circumflex = Â
  "45E2": "\u00CA", // E + circumflex = Ê
  "49E2": "\u00CE", // I + circumflex = Î
  "4FE2": "\u00D4", // O + circumflex = Ô
