    });

    const individuals: GedcomIndividualData[] = [
      {
        xref: "@I1@",
        name: "John /Smith/",
        notes: [],
        familiesAsSpouse: ["@F1@"],
        familiesAsChild: [],
      },
    ];

    const families: GedcomFamilyData[] = [
      {
        xref: "@F1@",
        children: [],
        marriageDate: "2000-06-15",
