  });

  it("should preserve international characters (José, Müller, François) through roundtrip", () => {
    const internationalGedcom = `0 HEAD
1 SOUR TestApp
1 GEDC
2 VERS 5.5.1
1 CHAR UTF-8
0 @I1@ INDI
1 NAME José /Ramírez/
0 @I2@ INDI
1 NAME Müller /Schäfer/
