  // Match ISO 8601 format
  const iso8601Match = dateStr.match(/^(\d{4})(?:-(\d{2})(?:-(\d{2}))?)?$/);

  if (!iso8601Match) {
    return null;
  }

  const year = iso8601Match[1];
  const month = iso8601Match[2];
  const day = iso8601Match[3];

